<span class="line">    <span class="token keyword">const</span> colorMapTex <span class="token operator">=</span> <span class="token constant">PIXI</span><span class="token punctuation">.</span>Texture<span class="token punctuation">.</span><span class="token function">from</span><span class="token punctuation">(</span>lutCanvas<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
