<span class="line">    <span class="token keyword">const</span> tex <span class="token operator">=</span> <span class="token keyword">await</span> <span class="token constant">PIXI</span><span class="token punctuation">.</span>Assets<span class="token punctuation">.</span><span class="token function">load</span><span class="token punctuation">(</span><span class="token string">&#39;./image/01.jpg&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
